@section('content')<div class="reader"><span class="tag">{{ $story->level }} · Đọc thử miễn phí</span><h1>{{ $story->title }}</h1><p>Chạm vào từ được gạch chân để xem nghĩa {{ config('learning.targets.'.$story->glossary_language) }}.</p><article style="color:var(--ink)">@foreach(preg_split('/\s+/', $story->body) as $word)@php($key=mb_strtolower(trim($word,".,!?;:\"")))@if(isset($story->glossary[$key]))<button class="word" type="button" data-meaning="{{ $story->glossary[$key] }}" style="text-decoration:underline;text-decoration-color:#9daf72">{{ $word }}</button>@else{{ $word }} @endif @endforeach</article><div class="notice" id="meaning" role="status" style="margin-top:24px;font:16px system-ui">Chọn một từ để khám phá.</div><details class="card" style="font:16px/1.7 system-ui" open><summary id="translation-label">Bản dịch</summary><label>Dịch sang<select id="sample-target">@foreach(config('learning.targets') as $key=>$label)<option value="{{ $key }}" @selected(request('target',auth()->user()?->translation_language ?? 'en')===$key)>{{ $label }}</option>@endforeach</select></label><p id="sample-translation" role="status">Đang dịch…</p><button id="retry-translation" class="btn secondary" type="button" hidden>Thử dịch lại</button></details><h2>Muốn ghi nhớ những từ này?</h2><p>Tạo tài khoản để lưu từ cùng câu ví dụ, ôn flashcard và theo dõi tiến độ.</p><a class="btn" href="{{ auth()->check()?'/catalogue/'.$story->id:'/register?story='.$story->id.'&target='.request('target',config('learning.default_target')) }}">{{ auth()->check()?'Vào thư viện':'Tạo tài khoản miễn phí' }}</a></div><script>document.querySelectorAll('[data-meaning]').forEach(b=>b.addEventListener('click',()=>{document.getElementById('meaning').textContent=b.textContent+' → '+b.dataset.meaning}));
const retryButton=document.getElementById('retry-translation');
let translationTimer, translationGeneration=0;
async function translateSample(attempt=0,generation){
    if(typeof attempt!=='number')attempt=0;
    if(attempt===0){clearTimeout(translationTimer);generation=++translationGeneration;}
    retryButton.hidden=true;document.getElementById('sample-target').disabled=true;
    const out=document.getElementById('sample-translation');out.textContent='Đang dịch…';
    try {const response=await fetch('/try/{{ $story->id }}/translate',{method:'POST',headers:{'Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content,'Content-Type':'application/json'},body:JSON.stringify({target:document.getElementById('sample-target').value})});const data=await response.json();if(!response.ok)throw new Error(data.message||'Không dịch được lúc này.');if(generation!==translationGeneration)return;if(['queued','processing'].includes(data.status)){if(attempt>=30)throw new Error('Dịch vẫn đang xử lý. Hãy thử lại sau.');out.textContent='Đang xử lý bản dịch…';translationTimer=setTimeout(()=>translateSample(attempt+1,generation),Math.min(15000,2000+attempt*1000));return;}if(['failed','unavailable'].includes(data.status))throw new Error(data.message);out.textContent=data.translation;document.getElementById('translation-label').textContent=data.review_status==='approved'?'Bản dịch đã duyệt':(data.provider.startsWith('Ollama:')?'Bản dịch AI local · '+data.provider.replace('Ollama:','').replace(/:literary-v\d+$/,''):'Bản dịch máy · MyMemory')+' (chưa duyệt)';}
    catch(error){out.textContent=error.message||'Không dịch được lúc này. Dịch vụ có thể mất kết nối hoặc hết hạn mức.';retryButton.hidden=false;}
    finally {document.getElementById('sample-target').disabled=false;}
}
document.getElementById('sample-target').addEventListener('change',translateSample);retryButton.addEventListener('click',translateSample);translateSample();
</script>@endsection
